import{_ as r,C as i,c as l,o as p,a3 as s,G as n,j as o,a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Applicant list","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/applicant-list.md","filePath":"master/human-resources/recruitment/applicants/applicant-list.md","lastUpdated":1793074831000}'),g={name:"master/human-resources/recruitment/applicants/applicant-list.md"};function c(d,t,h,u,_,m){const e=i("ImagePopup");return p(),l("div",null,[t[0]||(t[0]=s('<h1 id="applicant-list" tabindex="-1">Applicant list <a class="header-anchor" href="#applicant-list" aria-label="Permalink to &quot;Applicant list&quot;">​</a></h1><p>The applicant list shows every application in one table. You use it to find people, see who is in which stage, and open an applicant. Tabs, grouping, filters and columns let you answer questions such as &quot;Who is in the second interview?&quot;.</p><blockquote><p><strong>In simple words:</strong> One table of all applications, grouped by stage. Use tabs and filters to narrow it down.</p></blockquote><p>Open <code>Recruitments → Applications → Applicants</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page title is <strong>Applicants</strong>. <strong>New Applicant</strong> at the top right creates an application. See <a href="./add-applicant.html">Add an applicant</a>. Under the title you see the tabs. Below them are the <strong>Group by</strong> selector, the direction selector, the search box, the filter icon and the column icon.</p>',6)),n(e,{src:"/images1/recruitment/applicants_list_default.png",alt:"Applicants list on the Default tab with Group by set to Stage, applicants listed under stage headers and the columns Partner Name, Applied On and Job Position"}),t[1]||(t[1]=s('<p>Click a row to open the applicant. Each group header reads <strong>Stage: New</strong>, <strong>Stage: First Interview</strong> and so on. Click a header to collapse it.</p><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><p>The tabs are saved views. The row of tabs shows five of them:</p><ul><li><strong>Default:</strong> all applicants, grouped by <strong>Stage</strong>.</li><li><strong>My Applicants:</strong> applicants where you are the recruiter.</li><li><strong>Un Assigned:</strong> applicants without a recruiter.</li><li><strong>In Progress:</strong> applicants still in the process.</li><li><strong>Archived:</strong> inactive applicants, such as refused ones.</li></ul><p>Only <strong>Default</strong> groups the list by <strong>Stage</strong>. The other tabs start with <strong>Group by</strong> set to <code>-</code>, so the rows show in one flat list.</p>',5)),n(e,{src:"/images1/recruitment/applicants_list_tabs.png",alt:"Tabs Default, My Applicants, Un Assigned, In Progress and Archived with the In Progress tab selected and a flat list of applicants"}),t[2]||(t[2]=o("p",null,[a("Click the three dots next to the tabs. The "),o("strong",null,"Views"),a(" menu lists "),o("strong",null,"Favorite Views"),a(" (the tabs) and "),o("strong",null,"Preset Views"),a(". Click the three dots on a view to see "),o("strong",null,"Apply View"),a(" and "),o("strong",null,"Add to Favorites"),a(".")],-1)),n(e,{src:"/images1/recruitment/applicants_list_presets_menu.png",alt:"Views menu open with Favorite Views My Applicants, Un Assigned, In Progress and Archived, and Preset Views Hired, Refused, Blocked, Directly Available, Created Recently and Stage Updated Recently"}),t[3]||(t[3]=s('<ul><li><strong>Hired:</strong> applicants who reached a hired stage.</li><li><strong>Refused:</strong> applicants with the refused status.</li><li><strong>Blocked:</strong> applicants whose state is blocked.</li><li><strong>Directly Available</strong>, <strong>Created Recently</strong> and <strong>Stage Updated Recently</strong>: extra views you can apply. The last two list recent applicants.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A view shows rows only when applicants match it. For example, <strong>My Applicants</strong> lists applicants whose recruiter is you.</p></div><p>The <strong>Views</strong> menu also has <strong>Add New</strong> and <strong>Reset</strong> at the top.</p><h2 id="group-the-list" tabindex="-1">Group the list <a class="header-anchor" href="#group-the-list" aria-label="Permalink to &quot;Group the list&quot;">​</a></h2><p><strong>Group by</strong> starts on <strong>Stage</strong>. Choose another value:</p><ul><li><strong>Job Position</strong></li><li><strong>Candidate Name</strong></li><li><strong>Responsible</strong></li><li><strong>Creation Date</strong></li><li><strong>Hired Date</strong></li><li><strong>Last Stage</strong></li><li><strong>Refuse Reason</strong></li></ul><p>Choose the dash option (<code>-</code>) for no grouping. Set the direction to <strong>Ascending</strong> or <strong>Descending</strong>.</p>',7)),n(e,{src:"/images1/recruitment/applicants_list_group_by.png",alt:"Group by selector showing the options Stage, Job Position, Candidate Name, Responsible, Creation Date, Hired Date, Last Stage and Refuse Reason, next to the Ascending selector"}),t[4]||(t[4]=s('<h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>Three columns show at first: <strong>Partner Name</strong>, <strong>Applied On</strong> and <strong>Job Position</strong>. <strong>Partner Name</strong> is the candidate&#39;s full name. Click the column icon. A <strong>Columns</strong> panel opens with a checkbox for each column. Tick the ones you want, then click <strong>Apply columns</strong>. <strong>Reset</strong> restores the default columns. You can add:</p><p><strong>Stage</strong>, <strong>Candidate Name</strong>, <strong>Application Status</strong>, <strong>Refuse Reason</strong>, <strong>Evaluation</strong>, <strong>Tags</strong>, <strong>Email</strong>, <strong>Recruiter</strong>, <strong>Interviewer</strong>, <strong>Phone</strong>, <strong>Medium</strong>, <strong>Source</strong>, <strong>Expected Salary</strong> and <strong>Availability Date</strong>.</p>',3)),n(e,{src:"/images1/recruitment/applicants_list_columns.png",alt:"Columns panel with Partner Name, Applied On, Job Position, Stage, Recruiter and Expected Salary ticked and the Apply columns button"}),t[5]||(t[5]=s('<h2 id="search-and-filters" tabindex="-1">Search and filters <a class="header-anchor" href="#search-and-filters" aria-label="Permalink to &quot;Search and filters&quot;">​</a></h2><p>Type in the search box to find an applicant. Click the funnel icon to open <strong>Filters</strong>. Click <strong>Add rule</strong>, choose a field, then set the value. Click <strong>Apply filters</strong> to filter the list. You can filter by:</p><p><strong>Source</strong>, <strong>Medium</strong>, <strong>Candidate</strong>, <strong>Last Stage Updated</strong>, <strong>Stage</strong>, <strong>Job Position</strong>, <strong>Priority</strong>, <strong>Salary Proposed Extra</strong>, <strong>Salary Expected Extra</strong>, <strong>Applicant Notes</strong>, <strong>Applied On</strong> and <strong>Hired Date</strong>. <strong>OR condition</strong> combines rules.</p><p>For example, add a <strong>Job Position</strong> rule with <strong>Contains</strong> and pick <strong>Warehouse Supervisor</strong> to see only that job.</p>',4)),n(e,{src:"/images1/recruitment/applicants_list_filter.png",alt:"Filters panel with a Job Position rule set to Contains Warehouse Supervisor and the Add rule and Apply filters buttons"}),t[6]||(t[6]=s('<p>See <a href="./../../../getting-started/search-filter-group.html">Search, filter and group</a> for how filters work.</p><h2 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h2><p>The kebab menu on a row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. The clock icon opens the activity action. See <a href="./../../../getting-started/activities.html">Schedule an activity</a>. Use the checkboxes to select several rows.</p>',3)),n(e,{src:"/images1/recruitment/applicants_list_row_actions.png",alt:"Row menu opened from the three dots beside Rahul Verma with View, Edit and Delete"}),t[7]||(t[7]=s('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./process-applicant.html">Process an applicant</a></li><li><a href="./refuse-and-reopen.html">Refuse and reopen</a></li><li><a href="./../dashboard/recruitment-dashboard.html">Recruitment dashboard</a></li></ul>',2))])}const w=r(g,[["render",c]]);export{f as __pageData,w as default};
